mapper.codeEditorJavascript:
const MONTHS=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
const titles=(input.sheets||[]).map(s=>String((s.properties||{}).title||'').trim());
const nowIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'}));
const tabs=[];
for(let k=-1;k<=0;k++){const d=new Date(nowIL.getFullYear(),nowIL.getMonth()+k,1); const t=MONTHS[d.getMonth()]+' '+d.getFullYear(); if(titles.includes(t)) tabs.push(t);}
return {count:tabs.length, body: JSON.stringify({dataFilters: tabs.map(t=>({a1Range:"'"+t+"'!A1:AC3000"})), valueRenderOption:'FORMATTED_VALUE'})};

// input.ranges = valueRanges of the Pelephone sales tabs ; input.reps = rows of 'יעדים' (A:B) ; input.start = "YYYY-MM-DDTHH:MM" Israel time
const nowIL = new Date(new Date().toLocaleString('en-US', {timeZone: 'Asia/Jerusalem'}));
const start = input.start ? new Date(input.start) : new Date(2026, 9, 1);
const pad = n => String(n).padStart(2, '0');
const stamp = 'נשלח ' + pad(nowIL.getDate()) + '/' + pad(nowIL.getMonth() + 1) + ' ' + pad(nowIL.getHours()) + ':' + pad(nowIL.getMinutes());
const MARK_COL = 'AA';
const norm = s => String(s || '').replace(/\s+/g, ' ').trim();
// ---- reps
const ALIAS = {'אוסי': 'אוסי גיאן', 'עמית אראל': 'עמית הראל', 'אופק פ': 'אופק'};
const reps = [];
for (const r of (input.reps || []).slice(1)) {
  const name = norm(r[0]); let ph = String(r[1] || '').replace(/\D/g, '');
  if (!name || !ph) continue;
  if (ph.startsWith('972')) ph = ph.slice(3);
  ph = ph.replace(/^0/, '');
  if (/^5\d{8}$/.test(ph)) reps.push({name, wa: '972' + ph});
}
function findRep(raw) {
  let n = norm(raw); if (!n) return null;
  if (ALIAS[n]) n = ALIAS[n];
  let hit = reps.find(r => r.name === n); if (hit) return hit;
  const first = n.split(' ')[0];
  const byFirst = reps.filter(r => r.name.split(' ')[0] === first);
  if (byFirst.length === 1) return byFirst[0];
  return null;
}
// ---- parse "5.10 10-12"
function parseK(s) {
  s = String(s || '').trim();
  const m = s.match(/(\d{1,2})\s*[.\/]\s*(\d{1,2})(?:\s*[.\/]\s*(\d{2,4}))?\s+(\d{1,2})(?::(\d{2}))?\s*-+\s*(\d{1,2})(?::(\d{2}))?/);
  if (!m) return null;
  const day = +m[1], mon = +m[2] - 1;
  let year = m[3] ? +m[3] : nowIL.getFullYear();
  if (year < 100) year += 2000;
  if (!m[3] && mon > nowIL.getMonth() + 1) year -= 1;
  const endH = +m[6], endM = m[7] ? +m[7] : 0;
  if (mon < 0 || mon > 11 || day < 1 || day > 31 || endH > 23) return null;
  return new Date(year, mon, day, endH, endM);
}
const phoneOf = v => { let p = String(v || '').replace(/\D/g, ''); if (p.startsWith('972')) p = p.slice(3); return p.replace(/^0/, ''); };
// already-messaged phones (any tab)
const sentPhones = new Set();
for (const vr of (input.ranges || [])) for (const r of ((vr.valueRange || {}).values || []).slice(1)) if (norm(r[26])) sentPhones.add(phoneOf(r[3]));
const items = [];
const skipped = {notSim: 0, notWaiting: 0, sent: 0, noWindow: 0, notYet: 0, beforeStart: 0, badPhone: 0, noRep: 0};
for (const vr of (input.ranges || [])) {
  const tab = String((vr.valueRange || {}).range || '').split('!')[0].replace(/^'|'$/g, '');
  const vals = (vr.valueRange && vr.valueRange.values) || [];
  for (let i = 1; i < vals.length; i++) {
    const r = vals[i]; const rowNum = i + 1;
    const method = String(r[12] || '').toUpperCase().replace(/\s/g, '');
    if (method !== 'SIM' && method !== 'SIM/ESIM') { skipped.notSim++; continue; }
    if (norm(r[11]) !== 'ממתין לביצוע') { skipped.notWaiting++; continue; }
    if (norm(r[26])) { skipped.sent++; continue; }
    const end = parseK(r[10]);
    if (!end) { skipped.noWindow++; continue; }
    if (end > nowIL) { skipped.notYet++; continue; }
    if (end < start) { skipped.beforeStart++; continue; }
    const ph = phoneOf(r[3]);
    if (!/^5\d{8}$/.test(ph)) { skipped.badPhone++; continue; }
    if (sentPhones.has(ph)) { skipped.sent++; continue; }
    sentPhones.add(ph);
    const rep = findRep(r[0]);
    if (!rep) skipped.noRep++;
    const fullName = norm(r[2]);
    items.push({
      tab, row: rowNum, name: fullName, first: fullName.split(' ')[0] || fullName,
      wa: '972' + ph, phone: '0' + ph, k: String(r[10] || ''),
      repName: rep ? rep.name : norm(r[0]), repWa: rep ? rep.wa : '',
      markBody: JSON.stringify({valueInputOption: 'RAW', data: [
        {range: "'" + tab + "'!" + MARK_COL + '1', values: [['הודעת סימים']]},
        {range: "'" + tab + "'!" + MARK_COL + rowNum, values: [[stamp]]}
      ]})
    });
  }
}
return {count: items.length, items, skipped: JSON.stringify(skipped)};
